{"path": "src/App.jsx", "content": "import { useState, useEffect, useCallback } from 'react'

// Pyth MCP Helper
async function pythMCP(toolName, args) {
  // Step 1: Initialize session
  const init = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 0, method: 'initialize',
      params: { protocolVersion: '2024-11-05', capabilities: {}, clientInfo: { name: 'dada-game', version: '1.0' } }
    })
  });
  await init.json();

  // Step 2: Call the tool
  const res = await fetch('https://mcp.pyth.network/mcp', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
    body: JSON.stringify({
      jsonrpc: '2.0', id: 1, method: 'tools/call',
      params: { name: toolName, arguments: args }
    })
  });
  const data = await res.json();
  const text = data.result?.content?.[0]?.text || '';
  return JSON.parse(text);
}

function App() {
  const [currentPrice, setCurrentPrice] = useState(null)
  const [startPrice, setStartPrice] = useState(null)
  const [endPrice, setEndPrice] = useState(null)
  const [prediction, setPrediction] = useState('')
  const [timeLeft, setTimeLeft] = useState(30)
  const [gameState, setGameState] = useState('waiting') // waiting, active, ended, results
  const [roundResults, setRoundResults] = useState(null)
  const [totalScore, setTotalScore] = useState(0)
  const [roundNumber, setRoundNumber] = useState(1)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(true)

  // Fetch current BTC price
  const fetchBTCPrice = useCallback(async () => {
    try {
      setError('')
      const data = await pythMCP('get_candlestick_data', {
        symbol: 'Crypto.BTC/USD',
        resolution: '1',
        hours_back: 1
      })

      if (data?.candles && data.candles.length > 0) {
        // Get the latest candle
        const latestCandle = data.candles[data.candles.length - 1]
        const price = latestCandle.close
        setCurrentPrice(price)
        setLoading(false)
        return price
      } else {
        throw new Error('No price data available')
      }
    } catch (err) {
      console.error('Price fetch error:', err)
      setError('Unable to fetch Bitcoin price. Please try again.')
      setLoading(false)
      return null
    }
  }, [])

  // Start new round
  const startRound = useCallback(async () => {
    setLoading(true)
    const price = await fetchBTCPrice()
    if (price) {
      setStartPrice(price)
      setEndPrice(null)
      setPrediction('')
      setTimeLeft(30)
      setGameState('active')
      setRoundResults(null)
      setLoading(false)
    }
  }, [fetchBTCPrice])

  // End round and calculate results
  const endRound = useCallback(async () => {
    setLoading(true)
    const price = await fetchBTCPrice()
    if (price && startPrice) {
      setEndPrice(price)
      setGameState('ended')

      // Calculate actual volatility
      const actualVolatility = Math.abs((price - startPrice) / startPrice * 100)
      const predictedVolatility = parseFloat(prediction) || 0
      const difference = Math.abs(actualVolatility - predictedVolatility)

      // Score: 100 points if within ±0.1%, otherwise 0
      const score = difference <= 0.1 ? 100 : 0

      const results = {
        startPrice,
        endPrice: price,
        actualVolatility,
        predictedVolatility,
        difference,
        score,
        round: roundNumber
      }

      setRoundResults(results)
      setTotalScore(prev => prev + score)
      setGameState('results')
      setLoading(false)
    }
  }, [startPrice, prediction, roundNumber, fetchBTCPrice])

  // Next round
  const nextRound = () => {
    setRoundNumber(prev => prev + 1)
    startRound()
  }

  // Timer effect
  useEffect(() => {
    let interval
    if (gameState === 'active' && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            endRound()
            return 0
          }
          return prev - 1
        })
      }, 1000)
    }
    return () => clearInterval(interval)
  }, [gameState, timeLeft, endRound])

  // Initial load
  useEffect(() => {
    fetchBTCPrice()
  }, [fetchBTCPrice])

  // Update current price every 5 seconds when not in active round
  useEffect(() => {
    if (gameState !== 'active') {
      const interval = setInterval(fetchBTCPrice, 5000)
      return () => clearInterval(interval)
    }
  }, [gameState, fetchBTCPrice])

  const formatPrice = (price) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(price)
  }

  const formatPercent = (percent) => {
    return `${percent.toFixed(3)}%`
  }

  if (loading && !currentPrice) {
    return (
      <div className="game-container">
        <h1 className="title">DADA</h1>
        <p className="loading">Loading Bitcoin price...</p>
      </div>
    )
  }

  return (
    <div className="game-container">
      <h1 className="title">DADA</h1>
      <p className="subtitle">Bitcoin Volatility Prediction Game</p>

      {error && (
        <div className="error">{error}</div>
      )}

      <div className="price-section">
        <div className="current-price">
          {currentPrice ? formatPrice(currentPrice) : 'Loading...'}
        </div>
        <div className="price-info">
          Current Bitcoin Price
        </div>
      </div>

      <div className="game-section">
        {gameState === 'waiting' && (
          <>
            <div className="round-info">
              <div className="round-status">Ready to start Round {roundNumber}</div>
            </div>
            <button 
              className="predict-button" 
              onClick={startRound}
              disabled={loading}
            >
              Start Round
            </button>
          </>
        )}

        {gameState === 'active' && (
          <>
            <div className="round-info">
              <div className="timer">{timeLeft}s</div>
              <div className="round-status">Round {roundNumber} - Predict volatility!</div>
              <div className="price-info">Starting price: {formatPrice(startPrice)}</div>
            </div>

            <div className="prediction-section">
              <div className="input-group">
                <label>Volatility %:</label>
                <input
                  type="number"
                  step="0.001"
                  min="0"
                  max="20"
                  value={prediction}
                  onChange={(e) => setPrediction(e.target.value)}
                  placeholder="e.g. 1.250"
                  disabled={loading}
                />
              </div>
              <div style={{ fontSize: '0.9rem', opacity: '0.8', marginBottom: '1rem' }}>
                Predict how much Bitcoin's price will move in the next {timeLeft} seconds
              </div>
            </div>
          </>
        )}

        {gameState === 'ended' && (
          <div className="round-info">
            <div className="round-status">Round {roundNumber} ended - Calculating results...</div>
            {loading && <p className="loading">Fetching final price...</p>}
          </div>
        )}

        {gameState === 'results' && roundResults && (
          <>
            <div className="result-section">
              <div className="result-title">Round {roundResults.round} Results</div>
              <div className="result-details">
                <div>Start Price: {formatPrice(roundResults.startPrice)}</div>
                <div>End Price: {formatPrice(roundResults.endPrice)}</div>
                <div>Actual Volatility: {formatPercent(roundResults.actualVolatility)}</div>
                <div>Your Prediction: {formatPercent(roundResults.predictedVolatility)}</div>
                <div>Difference: {formatPercent(roundResults.difference)}</div>
              </div>
              <div className={`score-display ${roundResults.score > 0 ? 'score-positive' : 'score-zero'}`}>
                {roundResults.score > 0 ? '+' : ''}{roundResults.score} Points
                {roundResults.score > 0 && ' 🎯'}
              </div>
              {roundResults.score === 0 && (
                <div style={{ marginTop: '0.5rem', fontSize: '0.9rem', opacity: '0.8' }}>
                  You need to be within ±0.1% to score points
                </div>
              )}
            </div>

            <button 
              className="predict-button" 
              onClick={nextRound}
              disabled={loading}
            >
              Next Round
            </button>
          </>
        )}
      </div>

      <div className="score-section">
        <div>
          <strong>Total Score: {totalScore}</strong>
        </div>
        <div>
          Round: {roundNumber}
        </div>
      </div>
    </div>
  )
}

export default App"}

